const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Artiklid</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Saksa artiklit ei saa tuletada eesti keelest, sest eesti keeles grammatilist sugu ei ole. Seepärast on nimisõnu kõige parem õppida koos artikliga.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Artiklite näited</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — laud</div>\n      <div class=\"kurss-example\">die Tür — uks</div>\n      <div class=\"kurss-example\">das Messer — nuga</div>\n      <div class=\"kurss-example\">das Mädchen — tüdruk</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Sageli DER</h4>\n    <p class=\"artikuli-explain\">DER on sageli meessoost isikud, päevad, kuud, aastaajad ja mõned teatud lõpuga sõnad.</p>\n\n    <h5 class=\"artikuli-subtitle\">Reeglid</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → sageli DER, näiteks: der Computer, der Lehrer <span class=\"artikuli-note\">aga mitte alati</span></div>\n      <div class=\"kurss-example\">-ling → sageli DER, näiteks: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → sageli DER, näiteks: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">meessoost isikud → der Mann, der Vater</div>\n      <div class=\"kurss-example\">ametid → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">automargid → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">päevad → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">kuud → der August, der Dezember</div>\n      <div class=\"kurss-example\">aastaajad → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Näited</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — mees</div>\n      <div class=\"kurss-example\">der Vater — isa</div>\n      <div class=\"kurss-example\">der Montag — esmaspäev</div>\n      <div class=\"kurss-example\">der August — august</div>\n      <div class=\"kurss-example\">der Sommer — suvi</div>\n      <div class=\"kurss-example\">der Lehrer — õpetaja</div>\n      <div class=\"kurss-example\">der Computer — arvuti</div>\n      <div class=\"kurss-example\">der Schmetterling — liblikas</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Sageli DIE</h4>\n    <p class=\"artikuli-explain\">DIE on sageli naissoost isikud, mitmus ja sõnad lõpuga -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Reeglid</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">naissoost isikud → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">mootorrattamargid → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">mitmus → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">mitmus peaaegu alati → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Näited</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — naine</div>\n      <div class=\"kurss-example\">die Mutter — ema</div>\n      <div class=\"kurss-example\">die Wohnung — korter</div>\n      <div class=\"kurss-example\">die Rechnung — arve</div>\n      <div class=\"kurss-example\">die Freiheit — vabadus</div>\n      <div class=\"kurss-example\">die Möglichkeit — võimalus</div>\n      <div class=\"kurss-example\">die Mannschaft — meeskond</div>\n      <div class=\"kurss-example\">die Nation — rahvus</div>\n      <div class=\"kurss-example\">die Universität — ülikool</div>\n      <div class=\"kurss-example\">die Polizei — politsei</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Sageli DAS</h4>\n    <p class=\"artikuli-explain\">DAS on sageli deminutiivid lõpuga -chen / -lein, paljud sõnad lõpuga -ment / -um ning nimisõnadena kasutatud tegusõnad.</p>\n\n    <h5 class=\"artikuli-subtitle\">Reeglid</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">metallid → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">keemilised elemendid → das Eisen, das Kupfer</div>\n      <div class=\"kurss-example\">hotellid → das Hotel</div>\n      <div class=\"kurss-example\">värvid nimisõnadena → das Rot, das Blau</div>\n      <div class=\"kurss-example\">tegusõna nimisõnana → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">tegusõnad nimisõnadena → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Näited</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — laps</div>\n      <div class=\"kurss-example\">das Mädchen — tüdruk</div>\n      <div class=\"kurss-example\">das Häuschen — majake</div>\n      <div class=\"kurss-example\">das Instrument — instrument</div>\n      <div class=\"kurss-example\">das Zentrum — keskus</div>\n      <div class=\"kurss-example\">das Museum — muuseum</div>\n      <div class=\"kurss-example\">das Essen — söömine / toit</div>\n      <div class=\"kurss-example\">das Lernen — õppimine</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Olulised erandid / õpi koos artikliga</h4>\n    <p class=\"artikuli-explain\">Mõne sõna artiklit ei saa kindlalt määrata lõpu ega emakeele põhjal. Neid on kõige parem õppida koos artikliga.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — uks</div>\n      <div class=\"kurss-example\">das Messer — nuga</div>\n      <div class=\"kurss-example\">die Sonne — päike</div>\n      <div class=\"kurss-example\">der Mond — kuu</div>\n      <div class=\"kurss-example\">das Mädchen — tüdruk</div>\n      <div class=\"kurss-example\">das Auto — auto</div>\n      <div class=\"kurss-example\">der Käse — juust</div>\n      <div class=\"kurss-example\">die Gabel — kahvel</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Lõpud ja sõnarühmad aitavad artiklit ära arvata, kuid need ei ole 100% kindel reegel. Kui sa pole kindel, õpi sõna koos artikliga.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Asesõnad</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ ja Dativ — asesõnade vormid.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — kes?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — mina</div><div class=\"kurss-example\">du — sina</div><div class=\"kurss-example\">er — tema</div><div class=\"kurss-example\">sie — tema</div><div class=\"kurss-example\">es — see</div><div class=\"kurss-example\">wir — meie</div><div class=\"kurss-example\">ihr — teie</div><div class=\"kurss-example\">sie — nemad</div><div class=\"kurss-example\">Sie — Teie (viisakusvorm)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — keda?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — mind</div><div class=\"kurss-example\">dich — sind</div><div class=\"kurss-example\">ihn — teda (m.)</div><div class=\"kurss-example\">sie — teda (n.)</div><div class=\"kurss-example\">es — seda</div><div class=\"kurss-example\">uns — meid</div><div class=\"kurss-example\">euch — teid</div><div class=\"kurss-example\">sie — neid</div><div class=\"kurss-example\">Sie — Teid (viisakusvorm)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — kellele?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — mulle</div><div class=\"kurss-example\">dir — sulle</div><div class=\"kurss-example\">ihm — talle / sellele</div><div class=\"kurss-example\">ihr — talle</div><div class=\"kurss-example\">uns — meile</div><div class=\"kurss-example\">euch — teile</div><div class=\"kurss-example\">ihnen — neile</div><div class=\"kurss-example\">Ihnen — Teile (viisakusvorm)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Kuidas vormi valida?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — alus (kes teeb?)</li><li><span class=\"case-red\">Akkusativ</span> — otsene sihitis (keda?)</li><li><span class=\"case-green\">Dativ</span> — kaudne sihitis (kellele?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Näited</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Ma näen sind.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Ma näen teda.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Te meeldite meile.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Ma aitan sind.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Ma annan talle raamatu.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Me täname teid.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ on alati lause alus, Akkusativ ja Dativ aga sihitised. Vaata tegusõna ja küsi: <span class=\"case-red\">keda?</span> või <span class=\"case-green\">kellele?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Täishäälikud — pikad ja lühikesed</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Saksa keeles võivad täishäälikud olla pikad või lühikesed. See mõjutab sõna hääldust.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Pikk täishäälik</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">warm (varm) — soe</div><div class=\"kurss-example\">gut (guut) — hea</div><div class=\"kurss-example\">Tat (taat) — tegu / tegevus</div><div class=\"kurss-example\">Flur (fluur) — koridor / esik</div><div class=\"kurss-example\">Weg (veek) — tee</div><div class=\"kurss-example\">Hut (huut) — kübar</div><div class=\"kurss-example\">Hof (hoof) — õu / talu</div><div class=\"kurss-example\">Schlaf (šlaaf) — uni</div></div>\n              <p class=\"artikuli-explain\">Kui täishäälikule järgneb üks kaashäälik, hääldatakse täishäälikut sageli pikalt.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Lühike täishäälik</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Pilz (pilts) — seen</div><div class=\"kurss-example\">Wort (vort) — sõna</div><div class=\"kurss-example\">Mund (munt) — suu</div><div class=\"kurss-example\">bald (balt) — varsti</div><div class=\"kurss-example\">scharf (šarf) — terav</div><div class=\"kurss-example\">Feld (felt) — põld</div><div class=\"kurss-example\">voll (fol) — täis</div></div>\n              <p class=\"artikuli-explain\">Kui täishäälikule järgneb kaks või rohkem kaashäälikut, hääldatakse täishäälikut sageli lühidalt.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Lõpud en / el / er</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">singen (zingen) — laulma</div><div class=\"kurss-example\">tragen (traagen) — kandma</div><div class=\"kurss-example\">Garten (garten) — aed</div><div class=\"kurss-example\">Vogel (foogel) — lind</div><div class=\"kurss-example\">Segel (zeegel) — puri</div><div class=\"kurss-example\">Braten (braaten) — praad</div><div class=\"kurss-example\">Bogen (boogen) — kaar / poogen</div><div class=\"kurss-example\">Spiegel (špiigel) — peegel</div><div class=\"kurss-example\">Finger (finger) — sõrm</div><div class=\"kurss-example\">Halter (halter) — hoidja</div><div class=\"kurss-example\">Arbeiter (arbaiter) — tööline</div><div class=\"kurss-example\">Häuser (hoizer) — majad</div><div class=\"kurss-example\">wieder (viider) — jälle / uuesti</div><div class=\"kurss-example\">breiter (braiter) — laiem</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Täht h pikkuse märgina</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Rahmen (raamen) — raam</div><div class=\"kurss-example\">Ohr (oor) — kõrv</div><div class=\"kurss-example\">Kohle (koole) — süsi</div><div class=\"kurss-example\">Zahl (tsaal) — arv</div><div class=\"kurss-example\">ihn (iin) — teda (tema, mees)</div><div class=\"kurss-example\">ihm (iim) — temale (mees)</div><div class=\"kurss-example\">Huhn (huun) — kana</div><div class=\"kurss-example\">nahm (naam) — võttis</div><div class=\"kurss-example\">nehmen (neemen) — võtma</div><div class=\"kurss-example\">Schuh (šuu) — king</div></div>\n              <p class=\"artikuli-explain\">Mõnes sõnas pikendab h eelnevat täishäälikut. Sellistel juhtudel h-d tavaliselt ei hääldata.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Lõpud e-ga</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Lampe (lampe) — lamp</div><div class=\"kurss-example\">Hase (haaze) — jänes</div><div class=\"kurss-example\">Knabe (knaabe) — poiss</div><div class=\"kurss-example\">Rabe (raabe) — ronk</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Pikk i = ie</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">die (dii) — artikkel „die“</div><div class=\"kurss-example\">diese (diize) — see / need</div><div class=\"kurss-example\">wieder (viider) — jälle / uuesti</div><div class=\"kurss-example\">Fliege (fliige) — kärbes</div><div class=\"kurss-example\">Ziege (tsiige) — kits</div><div class=\"kurss-example\">Stiel (štiil) — vars</div><div class=\"kurss-example\">Dieb (diip) — varas</div><div class=\"kurss-example\">hier (hiir) — siin</div></div>\n              <p class=\"artikuli-explain\">Pikka i-d kirjutatakse saksa keeles sageli kui ie.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Topelttäishäälikud</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Saal (zaal) — saal</div><div class=\"kurss-example\">Saat (zaat) — külv / seeme</div><div class=\"kurss-example\">Staat (štaat) — riik</div><div class=\"kurss-example\">Beere (beere) — mari</div><div class=\"kurss-example\">See (zee) — järv / meri</div><div class=\"kurss-example\">Beet (beet) — peenar</div><div class=\"kurss-example\">Boot (boot) — paat</div><div class=\"kurss-example\">Moor (moor) — raba / soo</div><div class=\"kurss-example\">Moos (moos) — sammal</div></div>\n              <p class=\"artikuli-explain\">Topelttäishäälikuid hääldatakse tavaliselt pikalt.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ä</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Wand (vant) — sein</div><div class=\"kurss-example\">Wände (vende) — seinad</div><div class=\"kurss-example\">Vater (faater) — isa</div><div class=\"kurss-example\">Väter (feeter) — isad</div><div class=\"kurss-example\">Schrank (šrank) — kapp</div><div class=\"kurss-example\">Schränke (šrenke) — kapid</div><div class=\"kurss-example\">Bank (bank) — pink / pank</div><div class=\"kurss-example\">Bänke (benke) — pingid</div><div class=\"kurss-example\">Tal (taal) — org</div><div class=\"kurss-example\">Täler (teeler) — orud</div></div>\n              <p class=\"artikuli-explain\">ä on a umlaut.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ö</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Rose (rooze) — roos</div><div class=\"kurss-example\">Röschen (röös-hen) — roosike</div><div class=\"kurss-example\">Ofen (oofen) — ahi</div><div class=\"kurss-example\">Öfen (ööfen) — ahjud</div><div class=\"kurss-example\">Rock (rok) — seelik</div><div class=\"kurss-example\">Röcke (röke) — seelikud</div></div>\n              <p class=\"artikuli-explain\">ö on o umlaut.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ü</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">kurz (kurts) — lühike</div><div class=\"kurss-example\">kürzer (kürtser) — lühem</div><div class=\"kurss-example\">Kunst (kunst) — kunst</div><div class=\"kurss-example\">Künste (künste) — kunstid</div><div class=\"kurss-example\">Mutter (muter) — ema</div><div class=\"kurss-example\">Mütter (müter) — emad</div></div>\n              <p class=\"artikuli-explain\">ü on u umlaut.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Diftongid: äu</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Baum (baum) — puu</div><div class=\"kurss-example\">Bäume (boime) — puud</div><div class=\"kurss-example\">Haus (haus) — maja</div><div class=\"kurss-example\">Häuser (hoizer) — majad</div><div class=\"kurss-example\">Strauch (štrauh) — põõsas</div><div class=\"kurss-example\">Sträucher (štroiher) — põõsad</div><div class=\"kurss-example\">Maus (maus) — hiir</div><div class=\"kurss-example\">Mäuse (moize) — hiired</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Diftongid: eu</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">heute (hoite) — täna</div><div class=\"kurss-example\">Leute (loite) — inimesed</div><div class=\"kurss-example\">neu (noi) — uus</div><div class=\"kurss-example\">neun (noin) — üheksa</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Diftongid: ei</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">mein (main) — minu</div><div class=\"kurss-example\">dein (dain) — sinu</div><div class=\"kurss-example\">sein (zain) — tema (oma) / olema</div><div class=\"kurss-example\">frei (frai) — vaba</div><div class=\"kurss-example\">arbeiten (arbaiten) — töötama</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>2. tunni hääldusmärkused</h4>\n              <ul class=\"kurss-summary-list\"><li>sõnades ich, nicht, rechnen, zeichnen hääldatakse „ch“ pehmelt</li><li>sõnades arbeiten ja zeichnen hääldatakse „ei“ nagu „ai“</li><li>„sp“ hääldatakse sõna alguses nagu „šp“</li><li>tegusõnas tun hääldatakse „u“ pikalt</li></ul>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Kokkuvõte</h4>\n              <ul class=\"kurss-summary-list\"><li>üks kaashäälik täishääliku järel → sageli pikk täishäälik</li><li>kaks või rohkem kaashäälikut → sageli lühike täishäälik</li><li>h võib täishäälikut pikendada</li><li>ie tähendab sageli pikka i-d</li><li>topelttäishäälikud on tavaliselt pikad</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Kaashäälikud ja tähekombinatsioonid</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Saksa keeles hääldatakse mõnda kaashäälikut ja tähekombinatsiooni teisiti, kui neid kirjutatakse. Selles tunnis on algajale kõige olulisemad näited.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Kaashäälikud</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">das Rad (das raat) — ratas</div><div class=\"kurss-example\">die Räder (dii reeder) — rattad</div><div class=\"kurss-example\">Bad (baat) — vann / vannituba</div><div class=\"kurss-example\">Bäder (beeder) — vannid / vannitoad</div></div>\n              <p class=\"artikuli-explain\">Sõna lõpus ei hääldata kaashäälikuid sageli nii, nagu neid kirjutatakse.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ch</h4>\n              <p class=\"artikuli-explain\">„ch“ võib hääldada pehmelt või kõvalt. Mõnes sõnas kõlab see nagu eesti „h“, teistes lähemal „k“-le.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">rechnen (rehnen) — arvutama</div><div class=\"kurss-example\">zeichnen (tsaihnen) — joonistama</div><div class=\"kurss-example\">nicht (niht) — mitte / ei</div><div class=\"kurss-example\">schlecht (šleht) — halb</div><div class=\"kurss-example\">mich (mih) — mind</div><div class=\"kurss-example\">dich (dih) — sind</div><div class=\"kurss-example\">Strauch (štrauh) — põõsas</div><div class=\"kurss-example\">noch (noh) — veel</div><div class=\"kurss-example\">Nacht (naht) — öö</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>sch</h4>\n              <p class=\"artikuli-explain\">„sch“ hääldatakse saksa keeles nagu eesti „š“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Schule (šuule) — kool</div><div class=\"kurss-example\">Schüler (šüüler) — õpilane</div><div class=\"kurss-example\">Schiff (šif) — laev</div><div class=\"kurss-example\">Schraube (šraube) — kruvi</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>sp ja st sõna alguses</h4>\n              <p class=\"artikuli-explain\">Sõna või silbi alguses hääldatakse „sp“ sageli nagu „šp“ ja „st“ nagu „št“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">spielen (špiilen) — mängima</div><div class=\"kurss-example\">Sprung (šprung) — hüpe</div><div class=\"kurss-example\">stehen (štee-en) — seisma</div><div class=\"kurss-example\">Stall (štal) — laut / tall</div><div class=\"kurss-example\">Stand (štant) — seis / koht / müügilett</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>qu</h4>\n              <p class=\"artikuli-explain\">„qu“ hääldatakse saksa keeles tavaliselt nagu „kv“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Qual (kvaal) — piin</div><div class=\"kurss-example\">Quartier (kvartiir) — majutuskoht / kvartal</div><div class=\"kurss-example\">quer (kveer) — risti / põiki</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>s ja z</h4>\n              <p class=\"artikuli-explain\">Sõna alguses kõlab „s“ sageli nagu heliline „z“ (nagu inglise sõnas „zoo“). Täht „z“ kõlab saksa keeles nagu eesti „ts“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">sagen (zaagen) — ütlema</div><div class=\"kurss-example\">singen (zingen) — laulma</div><div class=\"kurss-example\">Rose (rooze) — roos</div><div class=\"kurss-example\">Zahl (tsaal) — arv</div><div class=\"kurss-example\">Zeit (tsait) — aeg</div><div class=\"kurss-example\">Zink (tsink) — tsink</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>v</h4>\n              <p class=\"artikuli-explain\">Saksa keeles hääldatakse „v“ sageli nagu „f“. Võõrsõnades kõlab see sageli nagu eesti „v“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Vater (faater) — isa</div><div class=\"kurss-example\">von (fon) — -st / -lt (kellelt, millest)</div><div class=\"kurss-example\">viel (fiil) — palju</div><div class=\"kurss-example\">vier (fiir) — neli</div><div class=\"kurss-example\">Villa (vila) — villa</div><div class=\"kurss-example\">Klavier (klaviir) — klaver</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>x ja y</h4>\n              <p class=\"artikuli-explain\">„x“ hääldatakse nagu „ks“. „y“ hääldatakse mõnes sõnas nagu „ü“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Felix (Feeliks) — Felix</div><div class=\"kurss-example\">Axt (akst) — kirves</div><div class=\"kurss-example\">Mystik (müstik) — müstika</div><div class=\"kurss-example\">Mythe (müüte) — müüt</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ß</h4>\n              <p class=\"artikuli-explain\">„ß“ hääldatakse saksa keeles nagu „s“.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Fuß (fuus) — jalalaba / jalg</div><div class=\"kurss-example\">Füße (füüse) — jalalabad / jalad</div><div class=\"kurss-example\">Grüße (grüüse) — tervitused</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Kokkuvõte</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → š</li><li>sp / st alguses → šp / št</li><li>qu → kv</li><li>z → ts</li><li>v sageli → f</li><li>x → ks</li><li>ß → s</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Tegusõnade alused</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>1. tunni tegusõnad ja nende vormid (pööramine)</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Tegusõnad</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">kommen — tulema</div><div class=\"kurss-example\">gehen — minema</div><div class=\"kurss-example\">stehen — seisma</div><div class=\"kurss-example\">singen — laulma</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>kommen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich komme — mina tulen</div><div class=\"kurss-example\">du kommst — sina tuled</div><div class=\"kurss-example\">er kommt — tema tuleb</div><div class=\"kurss-example\">sie kommt — tema tuleb</div><div class=\"kurss-example\">wir kommen — meie tuleme</div><div class=\"kurss-example\">ihr kommt — teie tulete</div><div class=\"kurss-example\">sie kommen — nemad tulevad</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>gehen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich gehe — mina lähen</div><div class=\"kurss-example\">du gehst — sina lähed</div><div class=\"kurss-example\">er geht — tema läheb</div><div class=\"kurss-example\">sie geht — tema läheb</div><div class=\"kurss-example\">wir gehen — meie läheme</div><div class=\"kurss-example\">ihr geht — teie lähete</div><div class=\"kurss-example\">sie gehen — nemad lähevad</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>stehen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich stehe — mina seisan</div><div class=\"kurss-example\">du stehst — sina seisad</div><div class=\"kurss-example\">er steht — tema seisab</div><div class=\"kurss-example\">sie steht — tema seisab</div><div class=\"kurss-example\">wir stehen — meie seisame</div><div class=\"kurss-example\">ihr steht — teie seisate</div><div class=\"kurss-example\">sie stehen — nemad seisavad</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>singen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich singe — mina laulan</div><div class=\"kurss-example\">du singst — sina laulad</div><div class=\"kurss-example\">er singt — tema laulab</div><div class=\"kurss-example\">sie singt — tema laulab</div><div class=\"kurss-example\">wir singen — meie laulame</div><div class=\"kurss-example\">ihr singt — teie laulate</div><div class=\"kurss-example\">sie singen — nemad laulavad</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>2. tunni tegusõnad</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">spielen — mängima</div><div class=\"kurss-example\">arbeiten — töötama</div><div class=\"kurss-example\">fragen — küsima</div><div class=\"kurss-example\">antworten — vastama</div><div class=\"kurss-example\">rechnen — arvutama</div><div class=\"kurss-example\">zeichnen — joonistama</div><div class=\"kurss-example\">tun — tegema</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>spielen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich spiele — mina mängin</div><div class=\"kurss-example\">du spielst — sina mängid</div><div class=\"kurss-example\">er spielt — tema mängib</div><div class=\"kurss-example\">sie spielt — tema mängib</div><div class=\"kurss-example\">wir spielen — meie mängime</div><div class=\"kurss-example\">ihr spielt — teie mängite</div><div class=\"kurss-example\">sie spielen — nemad mängivad</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>arbeiten</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich arbeite — mina töötan</div><div class=\"kurss-example\">du arbeitest — sina töötad</div><div class=\"kurss-example\">er arbeitet — tema töötab</div><div class=\"kurss-example\">sie arbeitet — tema töötab</div><div class=\"kurss-example\">wir arbeiten — meie töötame</div><div class=\"kurss-example\">ihr arbeitet — teie töötate</div><div class=\"kurss-example\">sie arbeiten — nemad töötavad</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>fragen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich frage — mina küsin</div><div class=\"kurss-example\">du fragst — sina küsid</div><div class=\"kurss-example\">er fragt — tema küsib</div><div class=\"kurss-example\">sie fragt — tema küsib</div><div class=\"kurss-example\">wir fragen — meie küsime</div><div class=\"kurss-example\">ihr fragt — teie küsite</div><div class=\"kurss-example\">sie fragen — nemad küsivad</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>antworten</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich antworte — mina vastan</div><div class=\"kurss-example\">du antwortest — sina vastad</div><div class=\"kurss-example\">er antwortet — tema vastab</div><div class=\"kurss-example\">sie antwortet — tema vastab</div><div class=\"kurss-example\">wir antworten — meie vastame</div><div class=\"kurss-example\">ihr antwortet — teie vastate</div><div class=\"kurss-example\">sie antworten — nemad vastavad</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>rechnen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich rechne — mina arvutan</div><div class=\"kurss-example\">du rechnest — sina arvutad</div><div class=\"kurss-example\">er rechnet — tema arvutab</div><div class=\"kurss-example\">sie rechnet — tema arvutab</div><div class=\"kurss-example\">wir rechnen — meie arvutame</div><div class=\"kurss-example\">ihr rechnet — teie arvutate</div><div class=\"kurss-example\">sie rechnen — nemad arvutavad</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>zeichnen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich zeichne — mina joonistan</div><div class=\"kurss-example\">du zeichnest — sina joonistad</div><div class=\"kurss-example\">er zeichnet — tema joonistab</div><div class=\"kurss-example\">sie zeichnet — tema joonistab</div><div class=\"kurss-example\">wir zeichnen — meie joonistame</div><div class=\"kurss-example\">ihr zeichnet — teie joonistate</div><div class=\"kurss-example\">sie zeichnen — nemad joonistavad</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>tun</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich tue — mina teen</div><div class=\"kurss-example\">du tust — sina teed</div><div class=\"kurss-example\">er tut — tema teeb</div><div class=\"kurss-example\">sie tut — tema teeb</div><div class=\"kurss-example\">wir tun — meie teeme</div><div class=\"kurss-example\">ihr tut — teie teete</div><div class=\"kurss-example\">sie tun — nemad teevad</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Lause ülesehitus</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Küsilauses on tegusõna saksa keeles tavaliselt esimesel kohal.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Näited</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Du kommst. — Sa tuled.</div><div class=\"kurss-example\">Kommst du? — Kas sa tuled?</div><div class=\"kurss-example\">Er singt. — Ta laulab.</div><div class=\"kurss-example\">Singt er? — Kas ta laulab?</div><div class=\"kurss-example\">Stehst du? — Kas sa seisad?</div><div class=\"kurss-example\">Ja, ich stehe. — Jah, ma seisan.</div><div class=\"kurss-example\">Geht ihr? — Kas te lähete?</div><div class=\"kurss-example\">Ja, wir gehen. — Jah, me läheme.</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Küsimused sõnaga „was“</h4>\n              <p class=\"artikuli-explain\">Kui küsimus algab küsisõnaga, on tegusõna saksa keeles tavaliselt kohe küsisõna järel.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Was tust du? — Mida sa teed?</div><div class=\"kurss-example\">Was tut er? — Mida ta teeb?</div><div class=\"kurss-example\">Was tut sie? — Mida ta teeb?</div><div class=\"kurss-example\">Was tun sie? — Mida nad teevad?</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Eitus sõnaga „nicht“</h4>\n              <p class=\"artikuli-explain\">Kui eitus „nicht“ käib tegusõna kohta, on see saksa keeles tavaliselt tegusõna järel.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich spiele nicht. — Ma ei mängi.</div><div class=\"kurss-example\">Paul fragt nicht. — Paul ei küsi.</div><div class=\"kurss-example\">Er kommt nicht. — Ta ei tule.</div><div class=\"kurss-example\">Sie singen nicht. — Nad ei laula.</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Laused 2. tunnist</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Spielst du? — Kas sa mängid?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Ei, ma ei mängi, ma töötan.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Paul ei küsi, ta töötab.</div><div class=\"kurss-example\">Arbeitest du? — Kas sa töötad?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Ei, ma ei tööta, ma laulan.</div><div class=\"kurss-example\">Was tut Paul? — Mida Paul teeb?</div><div class=\"kurss-example\">Er spielt. — Ta mängib.</div><div class=\"kurss-example\">Was tut Marie? — Mida Marie teeb?</div><div class=\"kurss-example\">Sie singt. — Ta laulab.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Paul mängib, aga Marie laulab.</div><div class=\"kurss-example\">Singt ihr? — Kas te laulate?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Ei, me ei laula, me töötame.</div><div class=\"kurss-example\">Was tun Paul und Marie? — Mida Paul ja Marie teevad?</div><div class=\"kurss-example\">Sie fragen. — Nad küsivad.</div><div class=\"kurss-example\">Sie antworten nicht. — Nad ei vasta.</div><div class=\"kurss-example\">Wer arbeitet? — Kes töötab?</div><div class=\"kurss-example\">Wir arbeiten. — Me töötame.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Me arvutame ja joonistame.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — Nad tulevad, küsivad, vastavad, töötavad, mängivad, laulavad ja lähevad.</div></div>\n            </section>",
  "kurssLesson1": "            <h3>Õppetund 1</h3>\n            <p class=\"kurss-lesson-intro\">Esimene õppetund: verbid olevikus, sõnad, hääldus, grammatika ja tõlkimine.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Verbid olevikus</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Verbid ja nende pööramine olevikus.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — tulema</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>mina tulen</span><span>du</span><strong>kommst</strong><span>sina tuled</span><span>er / sie</span><strong>kommt</strong><span>tema tuleb</span><span>wir</span><strong>kommen</strong><span>meie tuleme</span><span>ihr</span><strong>kommt</strong><span>teie tulete</span><span>sie / Sie</span><strong>kommen</strong><span>nemad tulevad / Teie tulete</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — minema</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>mina lähen</span><span>du</span><strong>gehst</strong><span>sina lähed</span><span>er / sie</span><strong>geht</strong><span>tema läheb</span><span>wir</span><strong>gehen</strong><span>meie läheme</span><span>ihr</span><strong>geht</strong><span>teie lähete</span><span>sie / Sie</span><strong>gehen</strong><span>nemad lähevad / Teie lähete</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — seisma</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>mina seisan</span><span>du</span><strong>stehst</strong><span>sina seisad</span><span>er / sie</span><strong>steht</strong><span>tema seisab</span><span>wir</span><strong>stehen</strong><span>meie seisame</span><span>ihr</span><strong>steht</strong><span>teie seisate</span><span>sie / Sie</span><strong>stehen</strong><span>nemad seisavad / Teie seisate</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — laulma</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>mina laulan</span><span>du</span><strong>singst</strong><span>sina laulad</span><span>er / sie</span><strong>singt</strong><span>tema laulab</span><span>wir</span><strong>singen</strong><span>meie laulame</span><span>ihr</span><strong>singt</strong><span>teie laulate</span><span>sie / Sie</span><strong>singen</strong><span>nemad laulavad / Teie laulate</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Näited</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Sõnad</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Sõnade ligikaudne hääldus on antud sulgudes eesti tähtedega.<br>Seda tuleb silmas pidada ka järgmistes õppetundides.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (viir) — meie</div><div class=\"kurss-example\">Sõnas “wir” hääldatakse i-d pikalt.</div><div class=\"kurss-example\">kommen (komen) — tulema</div><div class=\"kurss-example\">gehen (gee-en) — minema</div><div class=\"kurss-example\">stehen (shtee-en) — seisma</div><div class=\"kurss-example\">singen (zingen) — laulma</div><div class=\"kurss-example\">du (duu) kommst — sina tuled</div><div class=\"kurss-example\">er (eer) kommt — tema (mees) tuleb</div><div class=\"kurss-example\">sie (zii) kommt — tema (naine) tuleb</div><div class=\"kurss-example\">wer (veer) — kes?</div><div class=\"kurss-example\">ja (jaa) — jah</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Hääldus</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Sõnade õige hääldus on õppetundides antud eesti tähtedega.</div><div class=\"kurss-example\">Wir (viir) — meie. Sõnas wir hääldatakse i alati pikalt.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Infinitiiv</h4><div class=\"lesson1-grammar-note\">Verbi algvorm. Tavaliselt lõpeb infinitiiv lõpuga -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Oleviku lõpud</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Eemalda <span class=\"lesson1-ending-accent\">-en</span> verbi algvormist ja lisa lõpp.</strong></p><p>Näide: kommen → komm + lõpp</p><div class=\"lesson1-ending-process\" aria-label=\"Oleviku lõppude moodustamine\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>algvorm</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>eemalda <span class=\"lesson1-ending-accent\">-en</span></strong><span>jääb tüvi</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>tüvi</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>lisa lõpp</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Näited</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Küsilaused</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Saksa küsilauses liigub verb tavaliselt esimesele kohale.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Eesti keeles:<br>Sa tuled.<br>Kas sa tuled?</div><div class=\"kurss-example\">Saksa keeles:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — sina tuled<br>kommst du? — kas sina tuled?</div><div class=\"kurss-example\">er singt — tema laulab<br>singt er? — kas tema laulab?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Isiku erinevus</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — tema (mees) tuleb</div><div class=\"kurss-example\">sie kommt — tema (naine) tuleb</div><div class=\"kurss-example\">sie kommen — nemad tulevad</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Tõlgi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Õppetund 1: harjutuskaart\">\n                    <span class=\"lesson1-training-progress\">Õppetund 1 · Tõlgi: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Kas sa tuled?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Klõpsa kaardil, et näha saksakeelset tõlget. Pärast vastamist näitab järgmine klõps järgmist kaarti.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson2": "            <h3>Õppetund 2</h3>\n            <p class=\"kurss-lesson-intro\">Teine õppetund: dialoogid, sõnad, hääldus, grammatika ja tõlkimine.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoogid / laused</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Sõnad</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — mängima</div>\n                  <div class=\"kurss-example\">nein — ei</div>\n                  <div class=\"kurss-example\">nicht — mitte, ei</div>\n                  <div class=\"kurss-example\">arbeiten — töötama</div>\n                  <div class=\"kurss-example\">fragen — küsima</div>\n                  <div class=\"kurss-example\">was tut er? — mida ta teeb?</div>\n                  <div class=\"kurss-example\">was tun sie? — mida nad teevad?</div>\n                  <div class=\"kurss-example\">aber — aga</div>\n                  <div class=\"kurss-example\">antworten — vastama</div>\n                  <div class=\"kurss-example\">rechnen — arvutama</div>\n                  <div class=\"kurss-example\">zeichnen — joonistama</div>\n                  <div class=\"kurss-example\">Marie — Maarja</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Hääldus</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Sõnades ich, nicht, rechnen, zeichnen hääldatakse ch pehmelt, umbes nagu h eesti sõnades tehnika, Mihkel.</div><div class=\"kurss-example\">Sõnades arbeiten, zeichnen hääldatakse diftongi ei umbes nagu eesti ai.</div><div class=\"kurss-example\">Kaashäälikuühendit sp hääldatakse nagu shp: spielen (shpiilen).</div><div class=\"kurss-example\">Verbis tun hääldatakse u-d kõigis pööretes pikalt.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Lõpud e-ga</h4>\n                  <div class=\"lesson1-grammar-note\">Kui verbi tüvi lõpeb t, d või chn-ga, siis tuleb pööramisel lõppude -st ja -t ette e.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Küsisõna</h4>\n                  <div class=\"lesson1-grammar-note\">Küsilausetes, mis algavad küsisõnaga, näiteks mis? kes? milline? miks? mispärast? jne, asub verb kohe küsisõna järel.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — Mida sa teed?</div><div class=\"kurss-example\">Was tut er? — Mida ta (mees) teeb?</div><div class=\"kurss-example\">Was tut sie? — Mida ta (naine) teeb?</div><div class=\"kurss-example\">Was tun sie? — Mida nad teevad?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Eitus sõnaga nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Kui eitus nicht käib verbi kohta, asub eitussõna verbi järel.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — Ta ei tule.</div><div class=\"kurss-example\">Sie singen nicht. — Nad ei laula.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Tõlgi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Õppetund 2: tõlkekaart\">\n                    <span class=\"lesson1-training-progress\">Õppetund 2 · Tõlgi: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Kes küsib?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Klõpsa kaardil, et näha saksakeelset tõlget. Pärast vastamist näitab järgmine klõps järgmist kaarti.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson3": "            <h3>Õppetund 3</h3>\n            <p class=\"kurss-lesson-intro\">Kolmas õppetund: dialoogid, sõnad, hääldus, grammatika ja tõlkimine.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoogid / laused</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Sõnad</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — kes</div><div class=\"kurss-example\">was — mis</div><div class=\"kurss-example\">hier — siin</div><div class=\"kurss-example\">dort — seal</div><div class=\"kurss-example\">der Tisch — laud</div><div class=\"kurss-example\">ein Tisch — laud</div><div class=\"kurss-example\">die Bank — pink</div><div class=\"kurss-example\">eine Bank — pink</div><div class=\"kurss-example\">liegen — lamama</div><div class=\"kurss-example\">liegt hier ein Buch? — kas siin on / lebab raamat?</div><div class=\"kurss-example\">das Buch — raamat</div><div class=\"kurss-example\">ein Buch — raamat</div><div class=\"kurss-example\">hängen — rippuma</div><div class=\"kurss-example\">das Bild — pilt</div><div class=\"kurss-example\">ein Bild — pilt</div><div class=\"kurss-example\">die Tafel — tahvel</div><div class=\"kurss-example\">eine Tafel — tahvel</div><div class=\"kurss-example\">wie — milline</div><div class=\"kurss-example\">ist — on</div><div class=\"kurss-example\">dick — paks, jäme</div><div class=\"kurss-example\">das Heft — vihik</div><div class=\"kurss-example\">ein Heft — vihik</div><div class=\"kurss-example\">dünn — õhuke, peenike</div><div class=\"kurss-example\">niedrig — madal</div><div class=\"kurss-example\">hoch — kõrge</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Hääldus</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Pikka i-häälikut tähistatakse saksa keeles ie-ga: liegen (liigen), hier (hiir), wie (vii).</div><div class=\"kurss-example\">ck on kahekordne k: dick (dikk).</div><div class=\"kurss-example\">Omadus- ja määrsõnades kõlab lõpp -ig nagu kerge -ich: niedrig (niidrih).</div><div class=\"kurss-example\">Kui lõpule -ig järgneb e: -ige, siis hääldatakse g selge g-häälikuna: niedrige (niidrige) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Alus</h4><div class=\"lesson1-grammar-note\">Alus vastab saksa keeles küsimusele wer? / was? ja on nominatiivis.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Küsimusega wer? küsitakse isikute kohta.</div><div class=\"kurss-example\">Küsimusega was? küsitakse esemete kohta.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Artiklid</h4><div class=\"lesson1-grammar-note\">Saksa keeles on nimisõnal 3 sugu: meessugu, naissugu ja kesksugu. Nimisõna ees on tavaliselt väike sõna, mida nimetatakse artikliks. Seda sõna ei tõlgita.</div><h5 class=\"lesson2-subtitle\">Määrav artikkel</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">meessugu — der</div><div class=\"kurss-example\">naissugu — die</div><div class=\"kurss-example\">kesksugu — das</div><div class=\"kurss-example\">Mitmuses on määrav artikkel kõigi kolme soo puhul die.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Umbmäärane artikkel</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">meessugu — ein</div><div class=\"kurss-example\">naissugu — eine</div><div class=\"kurss-example\">kesksugu — ein</div><div class=\"kurss-example\">Umbmäärasel artiklil mitmust ei ole.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Pärisnimed</h4><div class=\"lesson1-grammar-note\">Pärisnimede ees artiklit ei kasutata.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Verbi koht</h4><div class=\"lesson1-grammar-note\">Jutustavas lauses on verb teisel kohal.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Saksa keeles öeldakse püstiasendis esemete kohta, et ese seisab:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">Horisontaalasendis olevate esemete kohta öeldakse, et need lamavad:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Esemed võivad ka rippuda:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Tõlgi</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Õppetund 3: tõlkekaart\"><span class=\"lesson1-training-progress\">Õppetund 3 · Tõlgi: 1 / 22</span><span class=\"lesson1-training-text\">Kas sa arvutad?</span></button><p class=\"lesson1-training-hint\">Klõpsa kaardil, et näha saksakeelset tõlget. Pärast vastamist näitab järgmine klõps järgmist kaarti.</p></div></div></details>",
  "kurssLesson4": "            <h3>Õppetund 4</h3>\n            <p class=\"kurss-lesson-intro\">Akusatiiv, nehmen, hinlegen, hinausgehen ja omadussõnad.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoogid / laused</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Sõnad</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (neemen) — võtma</div><div class=\"kurss-example\">er nimmt (nimt) — tema võtab</div><div class=\"kurss-example\">der Federhalter (deer feederhalter) — sulepea</div><div class=\"kurss-example\">einen Federhalter — sulepead</div><div class=\"kurss-example\">zeigen — näitama</div><div class=\"kurss-example\">schwarz (shvarts) — must</div><div class=\"kurss-example\">weiß (vais) — valge</div><div class=\"kurss-example\">die Feder (dii feeder) — sulg</div><div class=\"kurss-example\">eine Feder — sulge</div><div class=\"kurss-example\">spitz (shpits) — teravaotsaline</div><div class=\"kurss-example\">hinlegen — maha panema</div><div class=\"kurss-example\">legt hin — paneb maha</div><div class=\"kurss-example\">das Mädchen (meet-hen) — tüdruk</div><div class=\"kurss-example\">das Messer — nuga</div><div class=\"kurss-example\">ein Messer — nuga</div><div class=\"kurss-example\">scharf — terav</div><div class=\"kurss-example\">stumpf (shtumpf) — nüri</div><div class=\"kurss-example\">dann — siis</div><div class=\"kurss-example\">hinaus — välja</div><div class=\"kurss-example\">hinausgehen — välja minema</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Hääldus</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Lõpud -en, -er, -el on rõhuta, seepärast on e neis lõppudes vaevu kuuldav: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">h võib saksa keeles olla nii häälik kui ka eelneva täishääliku pikkuse märk.</div><div class=\"kurss-example\">Kui h on pikkuse märk, siis seda häälikuna ei hääldata: nehmen (neemen).</div><div class=\"kurss-example\">Kui täishäälikule järgneb ainult üks kaashäälik, hääldatakse täishäälikut pikalt: die (dii) Feder (feeder), den (deen).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Akusatiiv</h4><div class=\"lesson1-grammar-note\">Naissoos ja kesksoos on akusatiiv sama mis nominatiiv. Muutub ainult meessugu.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Asesõnad</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — meessugu</div><div class=\"kurss-example\">sie — naissugu</div><div class=\"kurss-example\">es — kesksugu</div><div class=\"kurss-example\">mitmuses — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Eraldatavad verbid</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Omadussõnad</h4><div class=\"lesson1-grammar-note\">Kui omadussõna on lauses öeldistäide, ei muutu see ei soo ega arvu järgi.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Eitus sõnaga nicht</h4><div class=\"lesson1-grammar-note\">Kui nicht eitab omadussõna, asub see eitatava sõna ees.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nimisõnad lõpuga -chen ja -lein on kesksoost: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Tõlgi</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Õppetund 4: tõlkekaart\"><span class=\"lesson1-training-progress\">Õppetund 4 · Tõlgi: 1 / 16</span><span class=\"lesson1-training-text\">Tüdruk võtab sulepea.</span></button><p class=\"lesson1-training-hint\">Klõpsa kaardil, et näha saksakeelset tõlget. Pärast vastamist näitab järgmine klõps järgmist kaarti.</p></div></div></details>",
  "kurssLesson5": "\n    <h3>Õppetund 5</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, akusatiiv, sitzen, fragen ja lõpp -in.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoogid / laused</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Sõnad</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (tsitsen) — istuma</div>\n        <div class=\"kurss-example\">fragen (fraagen) — küsima</div>\n        <div class=\"kurss-example\">der Lehrer (deer leerer) — õpetaja</div>\n        <div class=\"kurss-example\">gut (guut) — hästi</div>\n        <div class=\"kurss-example\">wen (veen) — keda</div>\n        <div class=\"kurss-example\">loben — kiitma</div>\n        <div class=\"kurss-example\">der Schüler (shüüler) — õpilane</div>\n        <div class=\"kurss-example\">klein — väike</div>\n        <div class=\"kurss-example\">groß (groos) — suur</div>\n        <div class=\"kurss-example\">die Lehrerin — õpetajanna</div>\n        <div class=\"kurss-example\">die Schülerin — koolitüdruk</div>\n        <div class=\"kurss-example\">schlecht (shleht) — halvasti</div>\n        <div class=\"kurss-example\">tadeln — laitma</div>\n        <div class=\"kurss-example\">oder (ooder) — või</div>\n        <div class=\"kurss-example\">das Kind (kint) — laps</div>\n        <div class=\"kurss-example\">artig (aartih) — sõnakuulelik</div>\n        <div class=\"kurss-example\">die Mutter — ema</div>\n        <div class=\"kurss-example\">lieben (liiben) — armastama</div>\n        <div class=\"kurss-example\">der Vater (faater) — isa</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Hääldus</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz on kahekordistatud z-häälik ja seda hääldatakse nagu ts: sitzen (tsitsen).</div>\n        <div class=\"kurss-example\">v-d hääldatakse saksa sõnades nagu f: der Vater (faater).</div>\n        <div class=\"kurss-example\">ß-i nimetatakse Eszett ja seda hääldatakse nagu eesti s: groß (groos), weiß (vais).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nominatiiv ja akusatiiv</h4><div class=\"lesson1-grammar-note\">Eesti keeles vastab nimetav kääne küsimusele kes? mis?, sihitis aga küsimusele keda? mida?.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Saksa keeles on nominatiivi küsimus isikute puhul wer? ja esemete puhul was?.</div><div class=\"kurss-example\">Akusatiivi küsimus on isikute puhul wen? ja esemete puhul was?.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Artiklite muutumine akusatiivis</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + akusatiiv</h4><div class=\"lesson1-grammar-note\">Saksa keeles nõuab verb fragen akusatiivi.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Lõpp -in</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paljud naissoost sõnad tuletatakse lõpuga -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Verbi koht</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Jutustavas lauses on verb teisel kohal.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Tõlgi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Õppetund 5: tõlkekaart\"><span class=\"lesson1-training-progress\">Õppetund 5 · Tõlgi: 1 / 16</span><span class=\"lesson1-training-text\">Keda isa armastab?</span></button><p class=\"lesson1-training-hint\">Klõpsa kaardil, et näha saksakeelset tõlget. Pärast vastamist näitab järgmine klõps järgmist kaarti.</p></div></div>\n    </details>\n  ",
  "kurssLesson6": "\n    <h3>Õppetund 6</h3>\n    <p class=\"kurss-lesson-intro\">Arvsõnad, mitmus, umlaudid ja nimisõnade mitmusevormid.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoogid / laused</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Sõnad</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — asub, on, lamab</div><div class=\"kurss-example\">der Bleistift (blaishtift) — pliiats</div><div class=\"kurss-example\">einige (ainige) — mõned</div><div class=\"kurss-example\">hinlegen — maha panema</div><div class=\"kurss-example\">legt hin — paneb maha</div><div class=\"kurss-example\">wieder (viider) — jälle</div><div class=\"kurss-example\">aufmachen — avama</div><div class=\"kurss-example\">er macht auf — tema avab</div><div class=\"kurss-example\">anspitzen (anshpitsen) — teritama</div><div class=\"kurss-example\">er spitzt an — tema teritab</div><div class=\"kurss-example\">sich setzen — istet võtma</div><div class=\"kurss-example\">setzt sich — võtab istet</div><div class=\"kurss-example\">der Schlüssel (shlüssel) — võti</div><div class=\"kurss-example\">das Fenster (fenster) — aken</div><div class=\"kurss-example\">die Tafel (dii taafel) — tahvel</div><div class=\"kurss-example\">der Garten — aed</div><div class=\"kurss-example\">der Löffel — lusikas</div><div class=\"kurss-example\">zählen (tseelen) — loendama</div><div class=\"kurss-example\">die Nadel — nõel</div><div class=\"kurss-example\">was ist das — mis see on?</div><div class=\"kurss-example\">der Hammer — haamer</div><div class=\"kurss-example\">die Hämmer — haamrid</div><div class=\"kurss-example\">der Deckel (deer dekel) — kaas</div><div class=\"kurss-example\">der Teller — taldrik</div><div class=\"kurss-example\">der Wagen — vanker</div><div class=\"kurss-example\">der Schlitten — kelk, regi</div><div class=\"kurss-example\">das Ding — asi</div><div class=\"kurss-example\">die Dinge — asjad</div><div class=\"kurss-example\">wie sind die Dinge? — millised on asjad?</div><div class=\"kurss-example\">voll (foll) — täis</div><div class=\"kurss-example\">leer (leer) — tühi</div><div class=\"kurss-example\">schwer (shveer) — raske</div><div class=\"kurss-example\">leicht — kerge</div><div class=\"kurss-example\">der Eimer — ämber</div><div class=\"kurss-example\">wieviel (viifiil) — mitu, kui palju</div><div class=\"kurss-example\">wieviel Nadeln — mitu nõela</div><div class=\"kurss-example\">hier (hiir) — siin</div><div class=\"kurss-example\">dort — seal</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Hääldus</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä on täishääliku a umlaut ja seda hääldatakse nagu lühikest või pikka kitsast e-d.</div><div class=\"kurss-example\">Näited: das Mädchen (meet-hen), die Bänke (dii benke), der Vater (deer faater), die Väter (dii feeter).</div><div class=\"kurss-example\">ü on täishääliku u umlaut ja seda hääldatakse nagu eesti ü. Selle hääldamisel tuleb huuled tugevalt ümardada ja püüda ümardatud huultega öelda i.</div><div class=\"kurss-example\">Näited: fünf, der Schlüssel (shlüssel).</div><div class=\"kurss-example\">ö-d hääldatakse nagu eesti ö, ümardatud huultega, püüdes öelda e: der Löffel.</div><div class=\"kurss-example\">Kahekordne täishäälik tähistab pikka täishäälikut: leer (leer).</div><div class=\"kurss-example\">Diftongi eu hääldatakse nagu oi: neun (noin).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatika</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Grammatika ja selgitused</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Liitverbi rõhuline eesliide eraldub olevikus verbist ja asub lause lõpus.</div><div class=\"kurss-example\">Näited: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">Arvsõnal üks on nimisõnaga kasutamisel kõik kolm sugu: meessoos ein, naissoos eine, kesksoos ein.</div><div class=\"kurss-example\">Näited: ein Schüler — üks õpilane; eine Schülerin — üks koolitüdruk; ein Kind — üks laps.</div><div class=\"kurss-example\">Arvsõnad: eins, zwei, drei, vier (fiir), fünf, sechs (zeks), sieben (ziiben), acht, neun (noin), zehn (tseen).</div><div class=\"kurss-example\">Saksa keeles on köiteverbil ainsuse ja mitmuse vorm: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">Eesti keeles muutub näitav asesõna see arvu järgi, mitmuses on need, kuid saksa keeles kasutatakse ainult üht vormi: das.</div><div class=\"kurss-example\">Näited: see on haamer — das ist ein Hammer; see on nõel — das ist eine Nadel; need on haamrid — das sind Hämmer; need on nõelad — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — vanker ja der Schlitten — kelk: saksa keeles kasutatakse neid sõnu nii ainsuses kui ka mitmuses.</div><div class=\"kurss-example\">Mees- ja kesksoost nimisõnad lõpuga -er, -el, -en ei saa mitmuses sageli lõppu.</div><div class=\"kurss-example\">Näited: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Naissoost nimisõnad lõpuga -el, -er saavad mitmuses lõpu -n.</div><div class=\"kurss-example\">Näited: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Erandid: die Mutter (ema) — die Mütter (emad); die Tochter (tütar) — die Töchter (tütred).</div><div class=\"kurss-example\">Umbmäärasel artiklil mitmust ei ole: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">Jutustavas lauses on öeldisverb teisel kohal: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Tõlgi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Õppetund 6: tõlkekaart\"><span class=\"lesson1-training-progress\">Õppetund 6 · Tõlgi: 1 / 21</span><span class=\"lesson1-training-text\">Paul võtab pliiatsi ja joonistab.</span></button><p class=\"lesson1-training-hint\">Klõpsa kaardil, et näha saksakeelset tõlget. Pärast vastamist näitab järgmine klõps järgmist kaarti.</p></div></div>\n    </details>\n  ",
  "kurssLesson7": "            <h3>Õppetund 7</h3>\n            <p class=\"kurss-lesson-intro\">Seitsmes õppetund: käskiv kõneviis, viisakas pöördumisvorm ja mitmus.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoogid / laused</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Sõnad</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — laulma</div><div class=\"kurss-example\">singe — laula</div><div class=\"kurss-example\">singt — laulge</div><div class=\"kurss-example\">singen Sie — laulge</div><div class=\"kurss-example\">das Lied (das liit) — laul</div><div class=\"kurss-example\">Sie — Teie</div><div class=\"kurss-example\">zählen — loendama</div><div class=\"kurss-example\">das Fräulein (froilain) — preili</div><div class=\"kurss-example\">der Müller — mölder</div><div class=\"kurss-example\">öffnen — avama</div><div class=\"kurss-example\">das Fenster (fenster) — aken</div><div class=\"kurss-example\">alle — kõik</div><div class=\"kurss-example\">der Spiegel (shpiigel) — peegel</div><div class=\"kurss-example\">der Lappen — lapp, kalts</div><div class=\"kurss-example\">der Spaten — labidas</div><div class=\"kurss-example\">der Besen — luud</div><div class=\"kurss-example\">die Schaufel — kühvel</div><div class=\"kurss-example\">die Schüssel — kauss</div><div class=\"kurss-example\">das Zimmer — tuba</div><div class=\"kurss-example\">das Ufer (uufer) — kallas</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Hääldus</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sp hääldatakse sõna või silbi alguses nagu shp: der Spiegel (deer shpiigel).</div><div class=\"kurss-example\">sch hääldatakse nagu sh-häälik: die Schaufel (dii shaufel), die Schüssel (dii shüssel).</div><div class=\"kurss-example\">Diftongi äu hääldatakse nagu eesti oi: das Fräulein (das froilain).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatika</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Käskiv kõneviis</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Käskiva kõneviisi ainsuse 2. pööre vastab verbi ainsuse 2. pöördele ilma isikulõputa -st, millele lisatakse lõpp -e.</div><div class=\"kurss-example\">Näited: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Väga sageli jäetakse lõpp -e ära, kui käsuvorm on ilma selleta ühesilbiline: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Mitmuse käskiv kõneviis</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Käskiva kõneviisi mitmuse 2. pööre on sama mis oleviku mitmuse 2. pööre, kuid seda kasutatakse ilma asesõnata.</div><div class=\"kurss-example\">Näited: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Viisakas pöördumisvorm Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Viisakas pöördumisvorm „Teie” vastab mitmuse 3. pöördele. Asesõna Sie kirjutatakse suure algustähega ja see asub verbi järel.</div><div class=\"kurss-example\">Näited: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Verbi öffnen puhul lisatakse hääldamise hõlbustamiseks ainsuse 2. ja 3. pöördes ning mitmuse 2. pöördes tüve ja lõpu vahele e: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Harjutus</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Õppetund 7: harjutuskaart\"><span class=\"lesson1-training-progress\">Õppetund 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — küsima</span></button><p class=\"lesson1-training-hint\">Puuduta kaarti, et näha käskiva kõneviisi vorme.</p></div></div></details>"
};

